using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options with a default resolver (handles common types) ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() – returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  →  Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() – probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded  →  {info!.Type.Name}");
}

// --- Options with a restricted resolver (source-gen context) ---
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = SmallContext.Default
};

// SmallContext only knows about WeatherForecast, not Person.
if (restricted.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("Person resolved (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false – no metadata (no exception!)");
}

// But WeatherForecast IS in the context:
if (restricted.TryGetTypeInfo<WeatherForecast>(out var wfInfo))
{
    Console.WriteLine($"TryGetTypeInfo<WeatherForecast> succeeded  →  {wfInfo!.Type.Name}");
}

// --- Types ---
public record Person(string Name, int Age);
public record WeatherForecast(string City, double TempC);

[JsonSerializable(typeof(WeatherForecast))]
internal partial class SmallContext : JsonSerializerContext;

